INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('2d4c8be6-7eab-4545-a5fc-2a56f2b5aa5b', 'Escalate overdue tickets', 'Raise an overdue ticket one step and tell the support managers.', 'ticket_overdue', '{"max_level":3}', '[{"type":"escalate_ticket"}]', 1, 240, 25, NULL, NULL, NULL, NULL, '2026-10-21T04:52:09.344Z', NULL, '2026-10-21T04:52:09.344Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('8ba45f7d-0721-4392-b013-e64c0791f7e1', 'Repeated integration failures → technical support', 'Tell technical support when a merchant''s integrations keep failing.', 'integration_failures', '{"hours":24,"min_errors":5}', '[{"type":"notify_staff","action":"edit","module":"integrations","severity":"WARN"},{"type":"notify_account_manager"}]', 1, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-21T04:52:09.344Z', NULL, '2026-10-21T04:52:09.344Z');
