INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('336bb9fb-2cab-4185-99d4-2fb8e9a5001e', 'Onboarding reminder', 'Remind merchants who have not finished setting up (in-app).', 'onboarding_incomplete', '{"days":3}', '[{"body":"A few setup steps are still open. Finish them to start taking orders smoothly — or reply to our support team if you need help.","kind":"GENERAL","link":"/admin","type":"notify_merchant","title":"Finish setting up your store","severity":"INFO"},{"type":"notify_account_manager","severity":"INFO"}]', 0, 4320, 25, NULL, NULL, NULL, NULL, '2026-10-21T04:52:09.344Z', NULL, '2026-10-21T04:52:09.344Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('53adaa80-a070-4e61-9b05-9401f1c0ffc8', 'Usage limit reached', 'Tell the merchant (in-app) and their account manager when SMS or BD Courier requests are refused.', 'usage_limit', '{"hours":24,"min_refused":1}', '[{"body":"Some SMS or courier history checks could not run because a limit or your credits ran out. Recharge or check your plan under Plan & Billing.","kind":"USAGE","link":"/admin/settings/billing","type":"notify_merchant","title":"A usage limit was reached","severity":"WARN"},{"type":"notify_account_manager","severity":"INFO"}]', 0, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-21T04:52:09.344Z', NULL, '2026-10-21T04:52:09.344Z');
